def test_a_jobs_log_goes_with_the_job_pruned_or_forgotten(bench: Bench) -> None:
    from datetime import UTC, datetime, timedelta

    from agentlint.forget import forget_everything
    from agentlint.store import retention

    db = connect()
    old, new = "2026-01-01T000000Z-000001", "2026-10-05T000000Z-000002"
    for job_id, when in ((old, "2026-01-01T00:00:00.000000+00:00"), (new, "2026-10-05T00:00:00.000000+00:00")):
        jobs.create(db, job_id=job_id, project="/p", fingerprint="fp", harness_version="1", model="m", run_ceiling=3,
                    timeout_s=30, plan='{"format": 3, "comparisons": []}', now=jobs.decode(when), harness="claude-code")
        jobs.close(db, job_id, JobStatus.COMPLETE)
        worker.log_path(job_id).parent.mkdir(parents=True, exist_ok=True)
        worker.log_path(job_id).write_text("a log\n")
    retention.prune(db, datetime(2026, 10, 5, tzinfo=UTC), 183)
    assert not worker.log_path(old).exists() and worker.log_path(new).exists()  # pruned with its job, the other kept
    forget_everything(db, datetime.now(UTC) + timedelta(seconds=1), [])
    assert not worker.log_path(new).exists()


def test_the_mac_is_kept_awake_while_a_worker_runs_and_only_on_a_mac() -> None:
    spawned: list[list[str]] = []

    class Spawned:
        pid = 1

        def wait(self) -> int:
            return 0

    def spawn(argv, **options):
        assert options["start_new_session"] is True  # Ctrl-C on the UI's terminal doesn't end it
        spawned.append(argv)
        return Spawned()

    table = ["  10 /usr/bin/python3 -m agentlint.runner j", "  11 caffeinate -i -w 999"]
    mac = KeepAwake(platform="darwin", which=lambda name: "/usr/bin/caffeinate", spawn=spawn,
                    table=lambda: "\n".join(table))
    assert mac.available and mac.holding(999) and not mac.holding(99)
    assert mac.hold(999) is True and spawned == []  # held already, by an earlier server
    assert mac.hold(1234) is True and spawned == [["caffeinate", "-i", "-w", "1234"]]
    assert "keeps this Mac from idle-sleeping (caffeinate -i)" in mac.line()
    other = KeepAwake(platform="linux", spawn=spawn)
    assert not other.available and other.hold(5) is False and len(spawned) == 1
    assert other.line().startswith("agentlint can't keep this machine awake")


def trace_of(*tools: str, version: str = "9.9.9", model: str = "model-x", skill: str | None = None) -> str:
    actions = [{"seq": i, "tool": tool, "input": {"file_path": f"/f{i}"}, "message_id": f"m{i}", "call_id": f"c{i}",
                "uses": [f"tools/{tool}"] + ([f"skills/{skill}"] if skill and tool == "Skill" else []),
                "answered": True, "error": False, "denied": False} for i, tool in enumerate(tools)]
    return json.dumps({"session_id": "s", "harness_version": version, "models": [model], "headless": True,
                       "actions": actions, "fired": []})


def test_results_are_the_stability_screen_by_the_set_of_tools_skills_and_agents_each_run_used() -> None:
    from datetime import UTC, datetime

    from agentlint.runner.plan import stability_plan
    from agentlint.ui.testing import situation_results

    at = datetime(2026, 10, 5, tzinfo=UTC)

    def run(key: str, trace: str, outcome: str = "ok") -> jobs.Run:
        return jobs.Run("j", key, "s", outcome, trace, "9.9.9", "model-x", 1000, None, at, at)

    plan = stability_plan([(f"p{i}", f"situation {i}", "rule") for i in range(1, 8)], runs=3)
    rows = [
        # disagreed: two runs read then edited (order and files ignored: one set), one ran a skill
        run("cmp-0001:baseline:0", trace_of("Read", "Edit")), run("cmp-0001:baseline:1", trace_of("Edit", "Read", "Read")),
        run("cmp-0001:baseline:2", trace_of("Skill", skill="tdd")),
        # agreed
        *(run(f"cmp-0002:baseline:{n}", trace_of("Bash")) for n in range(3)),
        # incomplete: two runs
        *(run(f"cmp-0003:baseline:{n}", trace_of("Bash")) for n in range(2)),
        # mixed environment: refused, at any count
        run("cmp-0004:baseline:0", trace_of("Bash")), run("cmp-0004:baseline:1", trace_of("Bash", version="9.9.8")),
        run("cmp-0004:baseline:2", trace_of("Bash")),
        # a timeout before anything was written: listed apart, never a run that did nothing
        run("cmp-0005:baseline:0", trace_of("Bash")), run("cmp-0005:baseline:1", trace_of("Bash")),
        run("cmp-0005:baseline:2", "null", outcome="timeout"),
        # no action: every run answered in words only — never agreed
        *(run(f"cmp-0006:baseline:{n}", trace_of()) for n in range(3)),
        # disagreed, though two of the runs took no action
        run("cmp-0007:baseline:0", trace_of()), run("cmp-0007:baseline:1", trace_of("Bash")),
        run("cmp-0007:baseline:2", trace_of()),
    ]
    found = {r["comparison"]: r for r in situation_results(plan, rows, "fp")}
    disagreed = found["cmp-0001"]
    assert (disagreed["state"], len(disagreed["runs"]), round(disagreed["modal_share"], 2)) == ("disagreed", 3, 0.67)
    assert [(b["runs"], b["count"], b["of"], b["used"]) for b in disagreed["branches"]] == [
        ([0, 1], 2, 3, {"tools": ["Edit", "Read"]}), ([2], 1, 3, {"skills": ["tdd"], "tools": ["Skill"]})]
    assert found["cmp-0002"]["state"] == "agreed" and found["cmp-0002"]["branches"][0]["of"] == 3
    assert (found["cmp-0003"]["state"], found["cmp-0003"]["progress"], found["cmp-0003"]["branches"]) == (
        "incomplete", "incomplete", [])
    assert (found["cmp-0004"]["state"], found["cmp-0004"]["differing"], found["cmp-0004"]["branches"]) == (
        "mixed environment", ["harness_version"], [])
    assert found["cmp-0005"]["state"] == "incomplete" and found["cmp-0005"]["unscreened"] == [
        {"run": 2, "outcome": "timeout", "seconds": 1.0}]
    assert [r["run"] for r in found["cmp-0005"]["runs"]] == [0, 1]  # the unread run is listed apart, not among them
    assert (found["cmp-0006"]["state"], found["cmp-0006"]["branches"]) == (
        "no action", [{"runs": [0, 1, 2], "count": 3, "of": 3, "used": {}}])
    assert found["cmp-0007"]["state"] == "disagreed"
    assert "stable" not in json.dumps(found)  # agreement is never called stable


def test_an_agreed_screen_at_ten_runs_keeps_the_run_that_differed_as_its_own_branch() -> None:
    from datetime import UTC, datetime

    from agentlint.runner.plan import stability_plan
    from agentlint.ui.testing import situation_results

    at = datetime(2026, 10, 5, tzinfo=UTC)
    plan = stability_plan([("p1", "situation", "rule")], runs=10)
