def test_a_situations_result_carries_its_with_without_verdict_and_each_target_its_verdict() -> None:
    """Both steps (D9): a situation whose runs agreed has its with/without comparison's verdict, measured from the runs
    recorded; one whose runs disagreed is skipped; one still short of its consistency runs is waiting; and a target's
    verdict is across its situations."""
    from datetime import UTC, datetime

    from agentlint.adapters.claude_code.terms import action_terms
    from agentlint.runner.plan import Planned, two_step_plan
    from agentlint.ui.testing import situation_results, target_results

    at = datetime(2026, 10, 6, tzinfo=UTC)

    def bash(*commands: str) -> str:
        actions = [{"seq": i, "tool": "Bash", "input": {"command": c}, "message_id": f"m{i}", "call_id": f"c{i}",
                    "uses": ["tools/Bash"], "answered": True, "error": False, "denied": False} for i, c in enumerate(commands)]
        return json.dumps({"session_id": "s", "harness_version": "9.9.9", "models": ["model-x"], "headless": True,
                           "actions": actions, "fired": []})

    def run(key: str, trace: str) -> jobs.Run:
        return jobs.Run("j", key, "s", "ok", trace, "9.9.9", "model-x", 1000, None, at, at)

    plan = two_step_plan([Planned("hook-a", (("p1", "Find the metrics"), ("p2", "Plan the pipeline")), True),
                          Planned("hook-b", (("p3", "Start a project"),), True)], runs=3, runs_per_side=5)
    # cmp-0001 (p1) agreed; cmp-0002 (p2) disagreed; cmp-0003 and cmp-0004 are their with/without comparisons;
    # cmp-0005 (p3) has two runs of three so far, and cmp-0006 is its with/without comparison.
    rows = [*(run(f"cmp-0001:baseline:{n}", bash("ls", "acme data.catalog fetch x | head")) for n in range(3)),
            run("cmp-0002:baseline:0", bash("ls")), run("cmp-0002:baseline:1", bash("ls")),
            run("cmp-0002:baseline:2", json.dumps({"session_id": "s", "harness_version": "9.9.9", "models": ["model-x"],
                                                   "headless": True, "actions": [], "fired": []})),
            *(run(f"cmp-0003:baseline:{n}", bash("ls", "acme data.catalog fetch x | head")) for n in range(5)),
            *(run(f"cmp-0003:without:{n}", bash("ls -la")) for n in range(5)),
            *(run(f"cmp-0005:baseline:{n}", bash("ls")) for n in range(2))]
    found = {r["comparison"]: r for r in situation_results(plan, rows, "fp", terms=action_terms)}
    assert set(found) == {"cmp-0001", "cmp-0002", "cmp-0005"}  # the situations; a with/without comparison is an effect
    measured = found["cmp-0001"]["effect"]
    assert (measured["state"], measured["comparison"], measured["measured"], measured["runs"]) == (
        "measured", "cmp-0003", "changes", {"baseline": 5, "without": 5})
    assert measured["evidence"] == [{"term": "shell:acme", "baseline": 5, "without": 0},
                                    {"term": "shell:head", "baseline": 5, "without": 0}]  # what changed; ls on both sides isn't
    assert measured["p"] < 0.05 and measured["tv"] == 1.0 and measured["canon"] == 1
    assert [r["run"] for r in measured["sides"]["without"]] == list(range(5))
    assert measured["sides"]["without"][0]["actions"] == [{"tool": "Bash", "what": "ls -la", "uses": {}}]
    assert found["cmp-0002"]["state"] == "disagreed" and found["cmp-0002"]["effect"]["state"] == "skipped"
    assert found["cmp-0002"]["effect"]["why"] == "disagreed"
    assert found["cmp-0005"]["effect"] == {"comparison": "cmp-0006", "planned": 5, "recorded": {"baseline": 0, "without": 0},
                                           "progress": "not-attempted", "state": "waiting"}
    targets = target_results(plan, list(found.values()), {"hook-a": "hook: SessionStart · a"})
    assert [(t["about"], t["name"], t["effect"]["measured"]) for t in targets] == [
        ("hook-a", "hook: SessionStart · a", "changes"), ("hook-b", "hook-b", "unmeasurable")]
    assert targets[0]["effect"]["situations"] == {"changes": 1, "no-change": 0, "unmeasurable": 1, "incomplete": 0}
    assert situation_results(plan, rows, "fp")[0]["effect"]["state"] == "unreadable"  # no adapter to read actions


def test_a_situation_whose_runs_agreed_but_never_did_what_it_expects_is_not_followed_and_never_run_without() -> None:
    from datetime import UTC, datetime

    from agentlint.adapters.claude_code.terms import action_terms
    from agentlint.runner.plan import Planned, two_step_plan
    from agentlint.ui.testing import situation_results

    at = datetime(2026, 10, 7, tzinfo=UTC)
